# Frozen Duck Core engine v4_0: generated by tools/freeze_engine.py from 79cc25d:src/duckmind/duckcore/graph.py; do not edit.
"""The duck's memory as a graph: people, distilled facts, episodes, and the voice lineage.

The optional "truth" layer adds the simulator's ground-truth personas so a viewer can see
what the duck cannot know (who actually touched it); the duck's own memory never
contains those nodes.
"""

from __future__ import annotations

from typing import Any

from duckmind.engines.v4_0.duckcore import content
from duckmind.engines.v4_0.duckcore.engine import DuckCore
from duckmind.engines.v4_0.duckcore.fixed import SCALE
from duckmind.engines.v4_0.duckcore.query import CATEGORY_ZH

HOUSEHOLD_SUBJECTS = {"家人", "我們家", "家裡", "我們"}


def build(core: DuckCore, *, truth: bool = False, episodes: int = 8) -> dict[str, Any]:
    memory = core.memory()
    s = core.s
    nodes: list[dict[str, Any]] = []
    edges: list[dict[str, Any]] = []
    stage = core.stage()
    nodes.append(
        {
            "id": "self",
            "type": "self",
            "label": s.name,
            "detail": f"{stage.zh}・成長日 {s.gd}",
            "strength": 100,
            "layer": "self",
        }
    )
    has_owner = any(fact.subject == "主人" for fact in memory.facts.values())
    has_household = any(fact.subject in HOUSEHOLD_SUBJECTS for fact in memory.facts.values())
    if has_owner:
        nodes.append(
            {
                "id": "owner",
                "type": "person",
                "label": "主人",
                "detail": f"親近 {s.bond_owner * 100 // SCALE}%（只來自主人手機）",
                "strength": s.bond_owner * 100 // SCALE,
                "layer": "L3",
            }
        )
        edges.append({"source": "self", "target": "owner", "type": "bond", "label": "親近"})
    if has_household:
        nodes.append(
            {
                "id": "household",
                "type": "person",
                "label": "家人",
                "detail": "牠分不出是誰，只知道「家裡有人」",
                "strength": 60,
                "layer": "L3",
            }
        )
        edges.append({"source": "self", "target": "household", "type": "bond", "label": "熟悉"})

    fact_ids = set()
    for fact in sorted(memory.facts.values(), key=lambda item: item.fact_id):
        node_type = "milestone" if fact.category == "milestone" else "fact"
        nodes.append(
            {
                "id": fact.fact_id,
                "type": node_type,
                "category": fact.category,
                "category_zh": CATEGORY_ZH.get(fact.category, fact.category),
                "label": fact.predicate if node_type == "fact" else fact.predicate or fact.text[:8],
                "detail": fact.text,
                "strength": fact.strength * 100 // SCALE,
                "recall": fact.recall(),
                "evidence_count": len(fact.evidence),
                "layer": "L3",
            }
        )
        fact_ids.add(fact.fact_id)
        if fact.subject == "主人" and has_owner:
            edges.append(
                {"source": "owner", "target": fact.fact_id, "type": "about", "label": "關於"}
            )
        elif fact.subject in HOUSEHOLD_SUBJECTS and has_household:
            edges.append(
                {"source": "household", "target": fact.fact_id, "type": "about", "label": "關於"}
            )
        else:
            edges.append(
                {"source": "self", "target": fact.fact_id, "type": "knows", "label": "記得"}
            )

    for episode in memory.episodes[-episodes:] if episodes > 0 else []:
        nodes.append(
            {
                "id": episode.episode_id,
                "type": "episode",
                "label": {
                    "visit": "拜訪",
                    "touch": "被摸",
                    "play": "陪玩",
                    "reunion": "招呼",
                    "walk": "散步",
                    "day": "一天",
                }.get(episode.kind, episode.kind),
                "detail": f"{episode.start.strftime('%m/%d %H:%M')} {episode.summary}",
                "strength": episode.salience * 100 // SCALE,
                "layer": "L2",
            }
        )
        ids = set(episode.event_ids)
        linked = False
        for fact in memory.facts.values():
            if ids & set(fact.evidence):
                edges.append(
                    {
                        "source": episode.episode_id,
                        "target": fact.fact_id,
                        "type": "supports",
                        "label": "支持",
                    }
                )
                linked = True
        if not linked:
            edges.append(
                {"source": "self", "target": episode.episode_id, "type": "lived", "label": "經歷"}
            )

    song_codes = set((s.song or {}).get("phrases", []))
    promoted_codes = {code for code, phrase in s.phrases.items() if phrase["promoted"]}
    kept_codes = sorted(
        (
            code
            for code, phrase in s.phrases.items()
            if phrase["promoted"]
            or code in song_codes
            or (
                phrase["liked_gds"]
                and any(parent in promoted_codes for parent in phrase["parents"])
            )
        ),
        key=lambda code: (
            -int(s.phrases[code].get("promoted_gd") or s.phrases[code]["born_gd"]),
            code,
        ),
    )[:16]
    for code, phrase in sorted(s.phrases.items()):
        # Keep the lineage readable: only the family's phrases, the song, and liked
        # children of family phrases. Random babbles are noise here.
        if code not in kept_codes:
            continue
        nodes.append(
            {
                "id": f"ph:{code}",
                "type": "phrase",
                "label": phrase["text"],
                "detail": f"第 {phrase['gen']} 代片語{'・被選中' if phrase['promoted'] else ''}・被誇 {phrase['praise']} 次",
                "strength": 80 if phrase["promoted"] else 35,
                "layer": "voice",
            }
        )
    phrase_nodes = {node["id"] for node in nodes if node["type"] == "phrase"}
    for code, phrase in sorted(s.phrases.items()):
        for parent in phrase["parents"]:
            if f"ph:{code}" in phrase_nodes and f"ph:{parent}" in phrase_nodes:
                edges.append(
                    {
                        "source": f"ph:{parent}",
                        "target": f"ph:{code}",
                        "type": "lineage",
                        "label": "演化",
                    }
                )
    if s.song is not None:
        nodes.append(
            {
                "id": "song",
                "type": "song",
                "label": "我們家的歌",
                "detail": f"第 {s.song['version']} 版",
                "strength": 90,
                "layer": "voice",
            }
        )
        edges.append({"source": "self", "target": "song", "type": "knows", "label": "會唱"})
        for code in s.song["phrases"]:
            if f"ph:{code}" in phrase_nodes:
                edges.append(
                    {"source": "song", "target": f"ph:{code}", "type": "part_of", "label": "收錄"}
                )
    if "F-fav-phrase" in fact_ids:
        favourite = memory.facts["F-fav-phrase"].value
        if f"ph:{favourite}" in phrase_nodes:
            edges.append(
                {
                    "source": "F-fav-phrase",
                    "target": f"ph:{favourite}",
                    "type": "about",
                    "label": "就是它",
                }
            )
    for phrase_id in phrase_nodes:
        if not any(edge["target"] == phrase_id for edge in edges):
            edges.append({"source": "self", "target": phrase_id, "type": "knows", "label": "會說"})

    if truth:
        persona_events: dict[str, set[str]] = {}
        for entry in core.journal:
            persona = entry.get("persona")
            if persona and entry.get("perceived"):
                persona_events.setdefault(persona, set()).update(entry.get("event_ids", []))
        for persona, event_ids in sorted(persona_events.items()):
            node_id = f"truth:{persona}"
            nodes.append(
                {
                    "id": node_id,
                    "type": "truth",
                    "label": f"{content.PERSONAS.get(persona, persona)}（真相）",
                    "detail": "模擬器才知道的真相；小鴨的記憶裡沒有這個人",
                    "strength": 40,
                    "layer": "truth",
                }
            )
            for fact in memory.facts.values():
                if event_ids & set(fact.evidence):
                    edges.append(
                        {
                            "source": node_id,
                            "target": fact.fact_id,
                            "type": "truth",
                            "label": "其實是我",
                        }
                    )
    return {
        "nodes": nodes,
        "edges": edges,
        "counts": {
            "facts": len(memory.facts),
            "episodes": len(memory.episodes),
            "phrases": len(phrase_nodes),
            "events": memory.source_count,
            "excluded": len(memory.excluded),
        },
    }
